+import React, { useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [displayName, setDisplayName] = useState(device.display_name);
+    const [newName, setNewName] = useState('');
+    const [isEditing, setIsEditing] = useState(false);
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+
+    const startEditing = () => {
+        setNewName(displayName ?? '');
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const save = async (event: React.FormEvent) => {
+        event.preventDefault();
+        if (isSaving) return;
+        if (newName === displayName) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, newName);
+            setDisplayName(newName);
+            setIsEditing(false);
+        } catch (error) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (isEditing) {
+        return <form data-testid='device-detail-name-edit' onSubmit={save}>
+            <label htmlFor={`device-name-${device.device_id}`}>{ _t('Session name') }</label>
+            <input
+                id={`device-name-${device.device_id}`}
+                data-testid='device-detail-name-input'
+                value={newName}
+                maxLength={100}
+                disabled={isSaving}
+                onChange={event => setNewName(event.target.value)}
+            />
+            <p>{ _t('Session names may be visible to others you communicate with.') }</p>
+            { error && <p role='alert'>{ error }</p> }
+            <button data-testid='device-detail-name-save' type='submit' disabled={isSaving}>{ _t('Save') }</button>
+            <button data-testid='device-detail-name-cancel'
+                type='button'
+                disabled={isSaving}
+                onClick={() => setIsEditing(false)}>{ _t('Cancel') }</button>
+            { isSaving && <span data-testid='device-detail-name-saving'><Spinner w={16} h={16} /></span> }
+        </form>;
+    }
+
+    return <div data-testid='device-detail-heading'>
+        <Heading size='h3'>{ displayName ?? device.device_id }</Heading>
+        <AccessibleButton kind='link_inline' data-testid='device-detail-rename' onClick={startEditing}>
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
